pub(crate) fn absorb_media(
    project: &mut Project,
    payload: &Payload,
    sources: &[u32],
    looks: &[u32],
) -> Result<HashMap<u32, u32>, String> {
    let mut map: HashMap<u32, u32> = HashMap::new();
    let mut appended: Vec<u32> = Vec::new();
    for (id, shown) in sources
        .iter()
        .map(|id| (*id, true))
        .chain(looks.iter().map(|id| (*id, false)))
    {
        if map.contains_key(&id) {
            continue;
        }
        let Some(entry) = payload.media.iter().find(|m| m.id == id) else {
            if shown {
                return Err(format!(
                    "a pasted clip shows media {id}, which the payload does not carry"
                ));
            }
            // A look's LUT the payload lacks (an end may name one that is
            // gone, spec §11 GR-8): left out of the map, so
            // `remap_look_media` makes it no look.
            continue;
        };
        let path = entry.path.trim().to_string();
        if path.is_empty() {
            return Err("a pasted media path must not be empty".to_string());
        }
        let local = match project.media.iter().find(|m| m.path == path) {
            Some(found) => found.id,
            None => {
                let mut record = entry.clone();
                record.path = path;
                // An empty bookmark is not a bookmark — `add_media`'s rule.
                record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
                // `add_media`'s own field checks, on the row as it would be
                // stored (issue #349), before it takes an id.
                record.original = normalize_original(record.original);
                check_media_fields(&record).map_err(|why| format!("pasted media {id}: {why}"))?;
                record.id = project.allocate_id();
                let new_id = record.id;
                project.media.push(record);
                appended.push(new_id);
                new_id
            }
        };
        map.insert(id, local);
    }
    for row in project.media.iter_mut() {
        if !appended.contains(&row.id) {
            continue;
        }
        if let Some(lut) = row.color.and_then(|color| color.lut) {
            match map.get(&lut) {
                Some(local) => {
                    if let Some(color) = row.color.as_mut() {
                        color.lut = Some(*local);
                    }
                }
                None => row.color = row.color.and_then(|color| color.without_camera_log()),
            }
        }
    }
    Ok(map)
}

/// The ids `absorb_media` resolves for `clips`, in the order they name
/// them (a `Vec` rather than a set, so the new rows are appended and
/// numbered reproducibly): the media each SHOWS, then the LUTs their looks
/// name (spec §11 GR-8) and the LUT each shown media's payload row converts
/// with (`color.lut`, GR-16).
fn wanted_media(clips: &[&Clip], payload: &Payload) -> (Vec<u32>, Vec<u32>) {
    let mut sources: Vec<u32> = Vec::new();
    let mut looks: Vec<u32> = Vec::new();
    for clip in clips {
        if let Some(id) = clip.source.media() {
            if !sources.contains(&id) {
                sources.push(id);
            }
        }
        for id in look_media_ids(clip)
            .into_iter()
            .chain(hide_silent_media(clip))
        {
            if !looks.contains(&id) {
                looks.push(id);
            }
        }
    }
    let converting = sources.iter().filter_map(|id| {
        let row = payload.media.iter().find(|m| m.id == *id)?;
        row.color?.lut
    });
    for id in converting.collect::<Vec<u32>>() {
        if !looks.contains(&id) {
            looks.push(id);
        }
    }
    (sources, looks)
}

/// Parses the payload, naming what was wrong.
pub(crate) fn parse_payload(payload: &Value) -> Result<Payload, String> {
    if !payload.is_object() {
        return Err(format!(
            "a paste payload must be a json object, not {}",
            describe(payload)
        ));
    }
    serde_json::from_value(payload.clone())
        .map_err(|e| format!("paste payload does not match the schema: {e}"))
}

impl Project {
    /// Inserts a clipboard payload's clips with fresh ids, the earliest one
    /// landing exactly at `at` and the rest keeping their offsets from it
    /// (spec §6).
    ///
    /// `track` names where the payload's front-most depth lands and retargets
    /// the rest by the same index delta, the way `move_clip` does; absent, it
    /// is the front-most track, so a paste keeps the copy's own layering.
    /// Tracks missing BEHIND the destination are added; a clip the overlap
    /// rule refuses on its target track goes on a new track in front.
    ///
    /// An identity for an empty clip list — the only answer that changes
    /// nothing, since the fallback track means a placement cannot fail.
    /// `Err` for a malformed payload, an unknown `track`, a clip naming a
    /// media the payload does not carry, a depth past the track cap, or a
    /// value out of range (`pasted clip N: …`, N the payload's id).
    pub fn paste(&self, at: Ticks, track: Option<u32>, payload: &Value) -> Result<Outcome, String> {
        let payload = parse_payload(payload)?;
        // An explicit destination is an id from THIS project, so an unknown
        // one is a caller bug and an error — unlike anything in the payload.
        // `tracks.len() - 1` is the front (index 0 is the back, spec §6); a
        // project with no tracks at all leaves it at -1, and the deficit
        // below adds the one every clip then needs.
        let base = match track {
            Some(id) => self.require_track_index(id)? as i64,
            None => self.tracks.len() as i64 - 1,
        };
        if payload.clips.is_empty() {
            return Ok(Outcome::Identity);
        }
        let deepest = payload.clips.iter().map(|c| c.track).max().unwrap_or(0) as i64;
        // Bounded BEFORE anything is allocated: `track` is a depth here, and
        // a payload claiming depth 4 000 000 000 would otherwise ask for four
        // billion tracks before `check_caps` ever saw the result.
        if deepest >= MAX_TRACKS as i64 {
            return Err(format!(
                "a pasted clip is {deepest} tracks deep, past the {MAX_TRACKS}-track limit"
            ));
        }
        let at = self.snapped(at).max(0);

        let mut next = self.clone();
        // The nests first, because their clips name media too: everything
        // that will land is resolved against `media[]` in one pass, and the
        // nests are then copied in with those ids already mapped.
        let nests = reachable_nests(&payload)?;
        let landing: Vec<&Clip> = payload
            .clips
            .iter()
            .chain(nests.iter().flat_map(|n| n.clips.iter()))
            .collect();
        let (sources, looks) = wanted_media(&landing, &payload);
        let media = absorb_media(&mut next, &payload, &sources, &looks)?;
        let nests = absorb_nests(&mut next, &nests, &media)?;

        // Tracks missing behind the destination. Inserting at index 0 shifts
        // every existing track up, so the destination index moves with them.
        let base = next.add_tracks_behind(deepest, base);

        // The earliest clip lands ON `at`, so every other one keeps its own
        // distance from it. Offsets are non-negative by construction, which
        // is what keeps a paste at 0 from folding clips onto each other.
        let earliest = payload.clips.iter().map(|c| c.start).min().unwrap_or(0);

        // Back-most depth first, then time: the order clips are placed in is
        // the order the overlap rule sees them, so it has to be deterministic
        // or the same payload could land two ways.
        let mut ordered: Vec<&Clip> = payload.clips.iter().collect();
        ordered.sort_by_key(|c| (std::cmp::Reverse(c.track), c.start, c.id));

        let mut landing = Landing::new(base);
        let first = next.clips.len();
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for source in ordered {
            let mut clip = source.clone();
            next.remint(&mut clip);
            fresh.insert(source.id, clip.id);
            clip.source = remap_source(&source.source, &media, &nests);
            remap_look_media(&mut clip, &media);
            remap_hide_silent(&mut clip, &media);
            // The payload is trusted about WHAT a clip is and checked about
            // what it would do to the project, so a nonsense rate — which
            // only a hand-written payload can carry — falls back to 1:1
            // rather than reaching the bound below and the composition.
            if !(clip.speed.is_finite() && clip.speed > 0.0) {
                clip.speed = 1.0;
            }
            clip.start = at.saturating_add(source.start.saturating_sub(earliest));
            // Checked on what the payload sent, before any snap (issue #62).
            next.normalise_and_check_pasted(&mut clip, source.id)?;
            // `next` and not `self`: the media this clip names was absorbed
            // into it above, and only a project that HOLDS the media can
            // measure how much window is left (spec §11, D4-4).
            next.resnap_clip_times(&mut clip);

            // The target track, then the fallbacks already added, then a new
            // one.
            landing.land(&mut next, clip, source.track as i64);
        }
        // A payload pair re-pairs through the fresh ids (spec §11 AU-96).
        if let Some(landed) = next.clips.get_mut(first..) {
            relink_copies(landed, &fresh);
        }

        self.finish_placement(next, landing.touched())
    }
}

//! `paste_attributes` — Edit ▸ Paste Attributes and Edit ▸ Paste Graphic
//! Properties (spec §6, table "Clips"; spec §11 G-32).
//!
//! Its own module because it is the clipboard's OTHER use: `paste` makes a
//! payload fit and places it, and this copies properties onto clips that
//! are already there and places nothing. The two share one thing, the
//! payload, whose shape stays `edit_paste.rs`'s to know and is read through
//! its [`parse_payload`]. Cut out of `edit_paste.rs` under the size rule
//! (core/CLAUDE.md), as a pure move, ahead of G-32.
//!
//! `paste_attributes` copies the EARLIEST payload clip's property groups
//! onto clips already on the timeline. It is not in `edit_props.rs` because
//! the material comes from the clipboard, not from a caller's patch. A
//! group is REPLACED whole, never merged — "make this look like that" is
//! the gesture, and a merge would leave the target's shadow under a source
//! that had none. What a target keeps is what makes it the clip it is
//! rather than how it looks: a text clip's `content` and the `words` that
//! time it (spec §11 W-6 — a timing belongs to its words); a shape's
//! `kind`, `width`, `height`, `from` and `to`. Video and audio travel whole,
//! transform included — `audio.muted` and `keep_pitch` are properties like
//! opacity, and `keep_pitch` only acts when the speed is not 1, which does
//! not travel: `speed`, `enabled`, the actions, the transition, the name,
//! the label and the source are not properties at all.
//!
//! **The qualifier follows the clip kind** (spec §11 GR-13): only an
//! adjustment clip takes one, so a picture target gets none (dropped, which
//! `paste_attributes`' description says — D2-1: a paste's answer is not
//! the place for it), and an adjustment target keeps its own when the
//! payload clip is a picture clip, which has none to give. Between two
//! adjustment clips it is copied like any other video key.
//!
//! ### The fifth group
//!
//! `graphic` (G-32) copies a graphic clip's `props`, whole, onto clips
//! drawn by the SAME module, and the target keeps its `name`, `width`,
//! `height`, `in` and `length`. It is a group a caller NAMES and never one
//! of the default set: props hold a graphic's words as well as its look,
//! and ⌥⌘V has no picker. That is why the names are [`PasteGroup`] and not
//! `patch::Group`: a patch has no `graphic` group (G-10), and `Group` is
//! matched exhaustively wherever a patch is read.
//!
//! The copied map is checked for SHAPE only — `model_graphic.rs`'s
//! `check_props` with no schema, then `check_count` — and only when a
//! target takes it, the first time one does: a paste in which no target
//! takes `graphic` never reads the map, as the four groups are checked
//! only after they have landed on a target. The write is `insert` and
//! `shift_remove`, `model_graphic.rs`'s rule, so a key both sides have
//! keeps its slot. A target key the payload lacks that an action on the
//! target names (`actions_graphic.rs`'s `names_prop`) is KEPT in its slot,
//! so the action's ramp keeps its start (spec §11 G-34 (d), amending
//! G-32 (e)).

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use crate::actions_graphic::names_prop;
use crate::edit_adjustment::is_adjustment;
use crate::edit_paste::{absorb_media, parse_payload};
use crate::lut::{look_media_ids, remap_look_media};
use crate::model::{Clip, GraphicProps, Project, Qualifier, ShapeProps, Source, TextProps};
use crate::model_graphic::{check_count, check_props};
use crate::outcome::Outcome;
use crate::patch::{Group, GROUPS};
use crate::video_gate::{hide_silent_media, remap_hide_silent};

/// The five groups `paste_attributes` takes by name — `video | audio | text
/// | shape | graphic` on the wire. The first four are the PATCH groups
/// ([`Group`]); `graphic` is the paste's alone (module doc).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PasteGroup {
    Video,
    Audio,
    Text,
    Shape,
    Graphic,
}

impl PasteGroup {
    /// The wire name, which is the patch group's own for the first four.
    pub(crate) fn name(self) -> &'static str {
        match self.layer() {
            Some(layer) => layer.name(),
            None => "graphic",
        }
    }

    /// The patch group this names, or `None` for `graphic`, which is not a
    /// group of the layer.
    fn layer(self) -> Option<Group> {
        match self {
            PasteGroup::Video => Some(Group::Video),
            PasteGroup::Audio => Some(Group::Audio),
            PasteGroup::Text => Some(Group::Text),
            PasteGroup::Shape => Some(Group::Shape),
            PasteGroup::Graphic => None,
        }
    }

    /// The same group as a name a caller could have sent.
    fn of(layer: Group) -> PasteGroup {
        match layer {
            Group::Video => PasteGroup::Video,
            Group::Audio => PasteGroup::Audio,
            Group::Text => PasteGroup::Text,
            Group::Shape => PasteGroup::Shape,
        }
    }
}

/// Whether a clip HAS the group — the model's only notion of what a clip
/// can take, the same one `edit_props.rs`'s patches go by.
fn has_group(clip: &Clip, group: Group) -> bool {
    match group {
        Group::Video => clip.video.is_some(),
        Group::Audio => clip.audio.is_some(),
        Group::Text => clip.text.is_some(),
        Group::Shape => clip.shape.is_some(),
    }
}

/// What a graphic clip is drawn from, or `None` for a clip that is not one
/// — `set_graphic`'s test: the source AND the description.
fn graphic_of(clip: &Clip) -> Option<&GraphicProps> {
    match clip.source {
        Source::Graphic => clip.graphic.as_ref(),
        _ => None,
    }
}

/// Whether a clip has a group a caller can name.
fn has(clip: &Clip, group: PasteGroup) -> bool {
    match group.layer() {
        Some(layer) => has_group(clip, layer),
        None => graphic_of(clip).is_some(),
    }
}

/// The copied props as they may be stored: shape-checked with no schema,
/// `null`s dropped, counted (G-32 (f)). The sentences are
/// `model_graphic.rs`'s own.
fn checked_props(from: &GraphicProps) -> Result<Map<String, Value>, String> {
    let mut stored = check_props(&from.props, None)?;
    stored.retain(|_, value| !value.is_null());
    check_count(&stored)?;
    Ok(stored)
}

/// Makes `into` hold exactly `props` plus the keys in `keep`: a key that
/// neither `props` nor `keep` holds is removed with `shift_remove`, a key
/// both maps have keeps its slot, a kept key keeps its slot and value, and
/// a new key is appended in `props`' order.
fn replace_props(into: &mut Map<String, Value>, props: &Map<String, Value>, keep: &[String]) {
    let gone: Vec<String> = into
        .keys()
        .filter(|key| !props.contains_key(*key) && !keep.contains(*key))
        .cloned()
        .collect();
    for key in gone {
        into.shift_remove(&key);
    }
    for (key, value) in props {
        into.insert(key.clone(), value.clone());
    }
}

/// Replaces `target`'s group with a copy of `source`'s, keeping the fields
/// that make the target the clip it is (module doc). A side that lacks the
/// group leaves the target as it was — the caller has already refused that
/// case by name, so this is only the shape that cannot invent a group.
fn copy_group(target: &mut Clip, source: &Clip, group: Group) {
    match group {
        Group::Video => {
            let picture_target = !is_adjustment(target);
            let picture_source = !is_adjustment(source);
            if let (Some(into), Some(from)) = (target.video.as_mut(), &source.video) {
                let own = into.qualifier;
                *into = from.clone();
                // The qualifier follows the clip kind (module doc, GR-13).
                if picture_target {
                    into.qualifier = Qualifier::default();
                } else if picture_source {
                    into.qualifier = own;
                }
            }
        }
        Group::Audio => {
            if let (Some(into), Some(from)) = (target.audio.as_mut(), &source.audio) {
                *into = *from;
            }
        }
        Group::Text => {
            if let (Some(into), Some(from)) = (target.text.as_mut(), &source.text) {
                let content = std::mem::take(&mut into.content);
                let words = std::mem::take(&mut into.words);
                *into = TextProps {
                    content,
                    words,
                    ..from.clone()
                };
            }
        }
        Group::Shape => {
            if let (Some(into), Some(from)) = (target.shape.as_mut(), &source.shape) {
                *into = ShapeProps {
                    kind: into.kind,
                    width: into.width,
                    height: into.height,
                    from: into.from,
                    to: into.to,
                    ..from.clone()
                };
            }
        }
    }
}

impl Project {
    /// Copies one payload clip's property groups onto every named clip (spec
    /// §6) — Edit ▸ Paste Attributes. The clip is the EARLIEST, then the
    /// front-most (`track` is a depth, 0 = front), then the lower id: Copy
    /// writes a selection in storage — creation — order, not the timeline's,
    /// so the array's first is a clip the user cannot see. Which fields
    /// travel, which a target keeps and why a group is replaced rather than
    /// merged are the module doc's.
    ///
    /// `groups` absent means every one of the four LAYER groups both sides
    /// have, silently skipping the rest: video onto a text clip from a media
    /// clip copies the video, leaves the text alone and drops the audio,
    /// which has nowhere to go. `graphic` is never in that set, and
    /// `skip_missing` changes nothing there. A NAMED group is different —
    /// one the source lacks is an `Err` naming the group, one a target lacks
    /// is `Err("clip N has no audio properties")`, the patches' answer, and
    /// `graphic` onto a clip drawn by another module is an `Err` naming both
    /// modules — because a caller who asked for it would otherwise never
    /// learn it did not happen. With `skip_missing` a caller says it does
    /// not need to: a named group the source lacks is dropped and a target
    /// that cannot take one is skipped for it (G-32). An empty explicit
    /// list, an identity paste and an empty selection are all identities.
    /// The copied layer groups then pass the range checks a patch does, so a
    /// payload written by hand cannot smuggle in a value the inspector would
    /// refuse; copied graphic props pass the shape check, the first time a
    /// target takes them.
    pub fn paste_attributes(
        &self,
        clips: &[u32],
        payload: &Value,
        groups: Option<&[PasteGroup]>,
        skip_missing: bool,
    ) -> Result<Outcome, String> {
        let payload = parse_payload(payload)?;
        let earliest = |c: &&Clip| (c.start, c.track, c.id);
        let Some(source) = payload.clips.iter().min_by_key(earliest) else {
            return Err("paste payload has no clips".to_string());
        };
        let mut named: Option<Vec<PasteGroup>> = None;
        if let Some(asked) = groups {
            let mut kept = Vec::new();
            for group in asked {
                if has(source, *group) {
                    kept.push(*group);
                } else if !skip_missing {
                    return Err(format!("payload clip has no {} properties", group.name()));
                }
            }
            named = Some(kept);
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();

        let mut next = self.clone();
        // Read at most once, by the first target that takes it (G-32 (f)).
        let mut copied: Option<Map<String, Value>> = None;
        // The source with its looks pointing at THIS project's LUTs, made by
        // the first target that takes the video group (spec §11 GR-8): the
        // LUTs it names are absorbed by path, as `paste` absorbs media, and
        // an id the payload lacks becomes no look.
        let mut looked: Option<Clip> = None;
        for id in ids {
            let Some(mut target) = next.clip(id).cloned() else {
                continue;
            };
            let chosen: Vec<PasteGroup> = match &named {
                Some(named) => named.clone(),
                None => GROUPS
                    .into_iter()
                    .filter(|g| has_group(source, *g) && has_group(&target, *g))
                    .map(PasteGroup::of)
                    .collect(),
            };
            let takes_video = chosen.contains(&PasteGroup::Video) && target.video.is_some();
            if takes_video && looked.is_none() {
                let looks = [
                    look_media_ids(source),
                    hide_silent_media(source).into_iter().collect(),
                ];
                let map = absorb_media(&mut next, &payload, &[], &looks.concat())?;
                let mut copy = source.clone();
                remap_look_media(&mut copy, &map);
                remap_hide_silent(&mut copy, &map);
                looked = Some(copy);
            }
            let from = looked.as_ref().unwrap_or(source);
            for group in chosen {
                if !has(&target, group) {
                    if skip_missing {
                        continue;
                    }
                    return Err(format!("clip {id} has no {} properties", group.name()));
                }
                let Some(layer) = group.layer() else {
                    let keep: Vec<String> = target.graphic.as_ref().map_or_else(Vec::new, |g| {
                        let named = g.props.keys().filter(|key| names_prop(&target, key));
                        named.cloned().collect()
                    });
                    let (Some(from), Some(into)) = (graphic_of(from), target.graphic.as_mut())
                    else {
                        continue;
                    };
                    if into.name != from.name {
                        if skip_missing {
                            continue;
                        }
                        return Err(format!(
                            "clip {id} is drawn by \"{}\" and the payload clip by \"{}\"; \
                             graphic props are pasted only between clips of one module",
                            into.name, from.name
                        ));
                    }
                    if copied.is_none() {
                        copied = Some(checked_props(from)?);
                    }
                    if let Some(props) = &copied {
                        replace_props(&mut into.props, props, &keep);
                    }
                    continue;
                };
                copy_group(&mut target, from, layer);
                next.normalise_and_check_group(&mut target, layer)?;
            }
            if let Some(slot) = next.clip_mut(id) {
                *slot = target;
            }
        }
        self.finish(next)
    }
}
                    self.snap_animation(text);
                }
            }
            Group::Shape => {
                if let Some(shape) = clip.shape.as_ref() {
                    check_shape(shape)?;
                }
            }
        }
        Ok(())
    }

    /// The clip's speed against `SPEED_MIN`–`SPEED_MAX`, then every group of
    /// one clip `paste` is about to land, through
    /// [`Self::normalise_and_check_group`] in [`GROUPS`] order, so a payload
    /// written by hand meets the bounds a patch does (issue #62, #206). A
    /// failure names the id the PAYLOAD gave the clip, the only one its
    /// writer knows. The callers have already reset a non-finite or
    /// non-positive speed to 1. The clip's own times are the caller's to
    /// re-snap, after this, at the speed checked here.
    pub(crate) fn normalise_and_check_pasted(
        &self,
        clip: &mut Clip,
        payload_id: u32,
    ) -> Result<(), String> {
        // Spelled as JSON spells it, as `validate`'s speed sentence is.
        if !(SPEED_MIN..=SPEED_MAX).contains(&clip.speed) {
            return Err(format!(
                "pasted clip {payload_id}: speed {} is outside ×{SPEED_MIN}–×{SPEED_MAX}",
                serde_json::Value::from(clip.speed)
            ));
        }
        for group in GROUPS {
            self.normalise_and_check_group(clip, group)
                .map_err(|why| format!("pasted clip {payload_id}: {why}"))?;
        }
        Ok(())
    }

    /// The one implementation behind the four `set_*` property ops: merge,
    /// check the keys against the group's schema, deserialize, range-check,
    /// store.
    ///
    /// A clip that does not HAVE the group is an error, not a silent skip:
    /// the group's presence is what "this clip has audio" / "this is a text
    /// clip" means, and inventing it would put text props on a video clip.
    fn patch_clips(&self, clips: &[u32], patch: &Value, group: Group) -> Result<Outcome, String> {
        if !patch.is_object() {
            return Err(format!(
                "{} patch must be a json object, not {}",
                group.name(),
                describe(patch)
            ));
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in ids {
            let clip = match next.clip(id) {
                Some(clip) => clip.clone(),
                None => continue,
            };
            match group {
                Group::Video => {
                    let base = clip
                        .video
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no video properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    normalise_look(&mut props, patch)?;
                    self.settle_video(&clip, &mut props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.video = Some(props);
                    }
                }
                Group::Audio => {
                    let base = clip
                        .audio
                        .ok_or_else(|| format!("clip {id} has no audio properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_audio(&props)?;
                    if sets_speech_duck(patch) && !self.has_speech(&clip) {
                        return Ok(Outcome::Refused(NEEDS_SPEECH.to_string()));
                    }
                    if let Some(slot) = next.clip_mut(id) {
                        slot.audio = Some(props);
                    }
                }
                Group::Text => {
                    let base = clip
                        .text
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no text properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    check_text(&props)?;
                    self.snap_animation(&mut props);
                    if let Some(slot) = next.clip_mut(id) {
                        slot.text = Some(props);
                    }
                }
                Group::Shape => {
                    let base = clip
                        .shape
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no shape properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_shape(&props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.shape = Some(props);
                    }
                }
            }
        }
        self.finish(next)
    }
}

