/// Edit ▸ Cut / Copy / Paste / Paste Attributes (⌘X, ⌘C, ⌘V, ⌥⌘V) — the
/// four menu items `EditorViewController.swift` forwards here — and the
/// fifth, Edit ▸ Paste Graphic Properties, whose action is this file's own.
///
/// The clipboard is one pasteboard type and two ops that read it. Copy writes
/// the selection as the `paste` op's payload (the module doc of
/// `core/src/edit_paste.rs` is its schema) under `com.kgalligan.framejob.clips`;
/// Paste hands that payload straight back to the core, which does all the
/// deciding — fresh ids, media matched by path, the overlap rule, the frame
/// grid — and Paste Attributes and Paste Graphic Properties hand the SAME
/// payload to `paste_attributes`, which reads only its earliest clip's
/// property groups. Nothing about a clip is interpreted on this side.
///
/// **Every reader and writer takes its pasteboard as a parameter**, the
/// general one by default, so a probe can drive Copy and both pastes over a
/// private pasteboard and never touch the owner's clipboard.
///
/// Two decisions worth stating, because neither is forced:
///
/// **The payload is built from the core's own project JSON, not from
/// `ProjectSnapshot`.** The snapshot is a LENIENT read view (its `init(from:)`
/// falls back rather than failing), so re-encoding one would quietly drop
/// whatever this build does not know about and round every field through
/// Swift's idea of the schema. Copying the raw JSON objects means a pasted
/// clip is the clip that was copied, down to the keys nobody has written yet.
///
/// **A payload clip's `track` is rewritten to a DEPTH from the front of the
/// stack** (0 = front-most), because a track id means nothing in another
/// document — and pasting between documents is the case the private
/// pasteboard type exists for. Depth is the only thing about the source's
/// track stack worth carrying: it is what makes a two-lane selection paste
/// back onto two lanes.
extension EditorViewController {
    /// The private pasteboard type the payload travels under. Private on
    /// purpose: a Frame Job clip is not a flavour of anything else, and a paste
    /// from another app is a beep, not a guess.
    static let clipsPasteboardType = NSPasteboard.PasteboardType("com.kgalligan.framejob.clips")

    // MARK: - Copy

    /// ⌘C. Writes the selection to the pasteboard (the general one, unless a
    /// probe names its own), with a short human summary as the plain-text
    /// fallback — pasting into a text editor should say what was copied, not
    /// spill a project.
    ///
    /// Returns whether anything was written, so Cut can stop before it deletes
    /// something it failed to copy.
    @discardableResult
    func copySelection(to pasteboard: NSPasteboard = .general) -> Bool {
        guard let document = document, !document.selection.isEmpty,
              let payload = clipboardPayload(for: document),
              JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(
                withJSONObject: payload, options: [.sortedKeys])
        else {
            NSSound.beep()
            return false
        }
        // `declareTypes` clears the pasteboard and takes ownership in one
        // call, which is the documented pairing for `setData(_:forType:)`.
        pasteboard.declareTypes([Self.clipsPasteboardType, .string], owner: nil)
        pasteboard.setData(data, forType: Self.clipsPasteboardType)
        pasteboard.setString(clipboardSummary(for: document), forType: .string)
        return true
    }

    /// The `paste` payload for the current selection: the selected clips
    /// verbatim out of `project.json` with each clip's `track` rewritten to
    /// its depth from the front, plus the media rows those clips name.
    ///
    /// nil when the project JSON cannot be read or the selection resolved to
    /// no clips at all — both of which mean there is nothing to put on the
    /// pasteboard, and the caller beeps.
    private func clipboardPayload(for document: ProjectDocument) -> [String: Any]? {
        // The EDITED project (road map 2's phase 9). Inside a nest the
        // selected clips are the NEST's, and they are the top level of this
        // JSON — so a Copy in a nest copies what was picked, and the `track`
        // depths it rewrites are counted against the nest's own stack, which

        // depths it rewrites are counted against the nest's own stack, which
        // is what the paste on the other side will be measured against.
        guard let data = document.editedProject.json.data(using: .utf8),
              let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let clips = root["clips"] as? [[String: Any]]
        else { return nil }
        let snapshot = document.editedProject.snapshot
        let front = snapshot.tracks.count - 1
        // A selected PICTURE half brings its linked sound, so a pasted
        // detached clip lands as a pair; a selected sound half is copied
        // alone, and the core clears its link on paste (spec §11 AU-96).
        var selection = document.selection
        for id in document.selection {
            if let clip = snapshot.clip(id), clip.enabled.video, let partner = clip.linked {
                selection.insert(partner)
            }
        }

        var payloadClips: [[String: Any]] = []
        var wanted: Set<UInt32> = []
        for clip in clips {
            guard let id = (clip["id"] as? NSNumber)?.uint32Value, selection.contains(id),
                  let track = (clip["track"] as? NSNumber)?.uint32Value,
                  let index = snapshot.trackIndex(of: track)
            else { continue }
            var copied = clip
            copied["track"] = front - index
            payloadClips.append(copied)
            wanted.formUnion(Self.payloadMediaIDs(clip))
        }
        guard !payloadClips.isEmpty else { return nil }
        // A wanted row's Camera Log LUT travels with it (spec §11 GR-16), so
        // the paste lands the conversion remapped rather than dropping it.
        for id in wanted {
            if let lut = snapshot.media(id)?.color?.lut { wanted.insert(lut) }
        }

        // Only the rows the copied clips SHOW or look through, and the LUTs
        // those convert with: a media entry nothing points at would arrive in
        // the other document as a Media-tab row the user cannot account for.
        let media = (root["media"] as? [[String: Any]] ?? []).filter { entry in
            guard let id = (entry["id"] as? NSNumber)?.uint32Value else { return false }
            return wanted.contains(id)
        }
        return ["clips": payloadClips, "media": media]
    }

    /// The media ids one copied clip (its `project.json` object) names: its
    /// source's, its base look's, its gate's (`video.hide_silent.media`, spec
    /// §11 CO-92) and each action end's look's (spec §11 GR-8), in that order
    /// without repeats — the rows a paste into another project needs. An end
    /// may name a LUT that is gone; its row is simply not found.
    static func payloadMediaIDs(_ clip: [String: Any]) -> [UInt32] {
        func lookMedia(_ video: Any?) -> UInt32? {
            guard let video = video as? [String: Any], let look = video["look"] as? [String: Any]
            else { return nil }
            return (look["media"] as? NSNumber)?.uint32Value
        }
        var found: [UInt32?] = [
            ((clip["source"] as? [String: Any])?["media"] as? NSNumber)?.uint32Value,
            lookMedia(clip["video"]),
            (((clip["video"] as? [String: Any])?["hide_silent"] as? [String: Any])?["media"]
                as? NSNumber)?.uint32Value,
        ]
        for action in clip["actions"] as? [[String: Any]] ?? [] {
            found.append(lookMedia((action["end"] as? [String: Any])?["video"]))
        }
        var ids: [UInt32] = []
        for id in found.compactMap({ $0 }) where !ids.contains(id) { ids.append(id) }
        return ids
    }

    /// The plain-text fallback: what was copied and the span it covered, in
    /// the document's own timecode (`ReelTime.format`, as everywhere else).
    private func clipboardSummary(for document: ProjectDocument) -> String {
        let clips = selectedClips
        let canvas = document.editedProject.snapshot.canvas
        let frames = canvas.timecodeFrames
        let start = clips.first?.start ?? 0
        let end = clips.map { $0.end }.max() ?? start
        let count = clips.count == 1 ? "1 clip" : "\(clips.count) clips"
        return "Frame Job — \(count), "
            + ReelTime.format(start, fps: canvas.fps, frames: frames) + " to "
            + ReelTime.format(end, fps: canvas.fps, frames: frames)
    }

    // MARK: - Cut

    /// ⌘X. Copy, then exactly the edit ⌫ performs — ONE undo step, because
    /// the copy touches no model state and the delete is a single op.
    func cutSelection() {
        guard let document = document, !document.selection.isEmpty else {
            NSSound.beep()
            return
        }
        guard copySelection() else { return }
        document.applyEdit("Cut", .delete(clips: Array(document.selection)))
    }

    // MARK: - Paste

    /// ⌘V. The payload lands at the playhead and whatever appeared is
    /// selected, so the paste can be dragged or styled straight away.
    ///
    /// Placement is entirely the core's: `paste` puts a clip the overlap rule
    /// refuses on a new track in front rather than refusing the edit, so the
    /// only beeps here are an empty pasteboard and a payload the core reports
    /// as invalid (through `applyEdit`, which presents the message).
    func pasteClips() {
        guard let document = document, let payload = pasteboardPayload() else {
            NSSound.beep()
            return
        }
        let before = document.editedProject.snapshot
        document.applyEdit("Paste", .paste(at: document.playhead, payload: payload))
        selectClips(addedSince: before, in: document)
    }

    // MARK: - Paste Attributes

    /// ⌥⌘V. The payload's EARLIEST clip's LOOK — its video, audio, text and
    /// shape groups, the earliest by start, then the front-most track, then
    /// the lower id — onto every selected clip, leaving `groups` to the core's
    /// default (every group both sides have, spec §6). Nothing that makes the
    /// clip THIS clip travels: not its place, speed, actions, transition, name
    /// or label, and not a text clip's words or a shape's geometry.
    ///
    /// Whole selection, one op, one undo step. An IDENTITY — the payload's
    /// clip and the targets share no group, or the look is already theirs —
    /// is `applyEdit`'s beep, and an out-of-range payload is its error,
    /// presented. There is no group picker here: the default rule is what
    /// ⌥⌘V has always meant in a cutting room, and the agent's tool
    /// (`paste_attributes`) takes `groups` for anyone who needs the choice.
    func pasteAttributes(from pasteboard: NSPasteboard = .general) {
        guard let document = document, !document.selection.isEmpty,
              let payload = pasteboardPayload(on: pasteboard)
        else {
            NSSound.beep()
            return
        }
        document.applyEdit(
            "Paste Attributes",
            .pasteAttributes(clips: Array(document.selection), payload: payload))
    }

    // MARK: - Paste Graphic Properties

    /// Edit ▸ Paste Graphic Properties (spec §11 G-32), which has no key. A
    /// menu sends its `NSMenuItem`, so the app reads the general pasteboard;
    /// a probe sends this action a private pasteboard as its sender, which
    /// is how the line below is measured and not only typechecked.
    @objc func pasteGraphicProperties(_ sender: Any?) {
        pasteGraphicProps(from: sender as? NSPasteboard ?? .general)
    }

    /// The copied graphic's props — all of them, its words included — onto
    /// every selected clip drawn by the SAME graphic; each keeps its own
    /// size, in point and length. ONE op, and nothing about the payload is
    /// read here: `groups: ["graphic"]` names the group ⌥⌘V never carries,
    /// and `skipMissing` makes the core skip a selected clip that cannot take
    /// it rather than refuse the paste. So when the copied clip is not a
    /// graphic, or no selected clip is drawn by the same one, the answer is
    /// an identity — `applyEdit`'s beep — and copied props the core will not
    /// store, onto a clip that takes them, are its sentence in an alert.
    func pasteGraphicProps(from pasteboard: NSPasteboard = .general) {
        guard let document = document, !document.selection.isEmpty,
              let payload = pasteboardPayload(on: pasteboard)
        else {
            NSSound.beep()
            return
        }
        document.applyEdit(
            "Paste Graphic Properties",
            .pasteAttributes(
                clips: Array(document.selection), payload: payload,
                groups: ["graphic"], skipMissing: true))
    }

    /// The payload on the pasteboard, or nil when there is nothing of ours
    /// there to paste — an empty pasteboard, another app's content, or a
    /// payload with no clips in it.
//! `nest` and `unnest` — grouping (spec §6, table "Clips").
//!
//! The two halves of one idea: a selection of clips becomes ONE clip on the
//! timeline showing a [`Nest`], and a nest clip becomes the clips again.
//! Their own module because grouping is a different concern from placement
//! — no other op changes which CONTAINER a clip lives in — and because the
//! pair only makes sense read together.
//!
//! ### They are inverses, up to ids
//!
//! `nest` then `unnest` gives back the clips it took: same sources, same
//! relative times, same props, same actions, same stacking. The ids differ,
//! exactly as they do across `split` then a re-join, because `unnest` mints
//! fresh ones — it has to, since a second clip may still show the same nest
//! and the clips inside it cannot be in two places at once.
//!
//! Two asymmetries are deliberate, and both come from the schema:
//!
//! - **A trimmed nest clip gives everything back.** `Source::Nest` has no in
//!   point (spec §5.2), so `unnest` is the inverse of `nest`, not of the
//!   trim that followed it: content the nest clip's edges were hiding
//!   reappears rather than being destroyed. Nothing is lost, and the user
//!   can trim again.
//! - **A clip the overlap rule refuses on the way out goes on a new track in
//!   front**, the fallback `paste` and Add Text already use (spec §6): a
//!   round trip lands on the tracks it came from because the nest clip's own
//!   span is free once it is removed, and only a nest that has since been
//!   moved next to other material needs the fallback. Refusing the whole op
//!   would leave the user with a group they cannot open.
//!
//! ### What `nest` decides
//!
//! The nest clip lands on the FRONT-most track the selection occupied that
//! is not a matte track (the front-most when all are, spec §11 MT-5), which
//! is where the selection's front-most DRAWN layer already was, and runs from
//! the earliest start to the latest end. The nest's own canvas is frozen at
//! the project's current size, so a later `set_canvas` cannot silently re-lay
//! out what is inside it ([`Nest`]). Its tracks are fresh — new ids, the
//! source tracks' names and their `hidden`/`muted`/`locked`/`solo` flags —
//! because the timeline's tracks stay on the timeline, holding whatever was
//! not selected. They copy each source track's `volume` and `pan` too, except
//! the copy of the nest clip's own destination track, which is unity and
//! centre: that track still applies over the nest clip, so a selection off one
//! track sounds the same nested, and the other source tracks' clips now also
//! get the destination's volume and pan on top of their own, as they get its
//! mute (spec §11 AU-102). `unnest` keeps neither, as it keeps no mute. A nested track keeps its source's `matte` only when the
//! nested track directly behind it is the copy of that matte's target (the
//! CARRY rule): a matte pair nested together goes on cutting inside the nest,
//! and a matte taken without its target becomes an ordinary track there.
//!
//! `unnest` lines the nest's front-most NON-matte track up with the nest
//! clip's track, so carried matte tracks land on the tracks in front of it
//! and nest-then-unnest gives the picture back; it makes no track a matte.

use std::collections::HashMap;

use crate::edit_adjustment::{adjustment_cannot_nest, is_adjustment};
use crate::edit_clip::clip_end;
use crate::edit_commit::Landing;
use crate::edit_link::relink_copies;
use crate::model::{AudioProps, Clip, Nest, Project, Source, Track, VideoProps};
use crate::outcome::Outcome;
use crate::recipe_matte::matte_target;

/// A track with a fresh id, copying `from`'s name and its hidden / muted /
/// locked / solo / matte state (the matte only provisionally: `nest_clips`
/// keeps it by the carry rule alone), and its volume and pan when
/// `keeps_mix` (spec §11 AU-102).
///
/// The state is copied and not cleared: a selection taken off a muted track
/// must go on sounding the way it did, and the mute now lives on the nest's
/// own track where the user can find it. Solo copies for the same reason —
/// what played before nesting plays after — even though a solo is judged
/// per container, so inside the nest it is now judged among the nest's own
/// tracks.
///
/// Volume and pan are copied from every source track but the nest clip's
/// destination, whose copy gets `keeps_mix` false and so unity and centre:
/// the destination track still applies over the nest clip, and a fader
/// applied twice is not a fader applied once (where muting twice is muting
/// once, so mute copies from it too).
///
/// A compressor or limiter is never copied (spec §11 AU-150): a nest's own
/// tracks have none, and the destination's still apply over the nest clip.
fn nested_track(project: &mut Project, from: &Track, keeps_mix: bool) -> Track {
    Track {
        id: project.allocate_id(),
        name: from.name.clone(),
        hidden: from.hidden,
        muted: from.muted,
        locked: from.locked,
        solo: from.solo,
        matte: from.matte,
        volume: if keeps_mix { from.volume } else { 1.0 },
        pan: if keeps_mix { from.pan } else { 0.0 },
        compressor: None,
        limiter: None,
    }
}

impl Project {
    /// Collapses `clips` into one nest clip (spec §6).
    ///
    /// The clips keep their relative times — the earliest starts at 0 inside
    /// the nest — their relative track order, their props and their actions;
    /// the nest clip covers exactly the span they covered, on the front-most
    /// track any of them was on.
    ///
    /// An empty selection, and a selection of one clip that is already a
    /// nest (grouping a group alone changes nothing a user can see), are
    /// identities. A nest clip that would break the overlap rule against
    /// whatever was NOT selected is refused, in the rule's own sentence. `Err` on an unknown clip id or a selection
    /// that would put the project past the track cap.
    pub fn nest_clips(&self, clips: &[u32], name: Option<&str>) -> Result<Outcome, String> {
        // A linked partner goes in with its clip (spec §11 AU-91).
        let selected: Vec<Clip> = self
            .selected_clips(&self.with_links(clips)?)?
            .into_iter()
            .cloned()
            .collect::<Vec<_>>();
        if selected.is_empty() {
            return Ok(Outcome::Identity);
        }
        if selected.len() == 1 && matches!(selected[0].source, Source::Nest { .. }) {
            return Ok(Outcome::Identity);
        }
        // An adjustment clip grades the top level only (spec §11 GR-6).
        if let Some(found) = selected.iter().find(|c| is_adjustment(c)) {
            return Ok(Outcome::Refused(adjustment_cannot_nest(found.id)));
        }

        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
        if latest <= earliest {
            return Ok(Outcome::Identity);
        }

        // The source tracks, back-most first, so the nest's own stack keeps
        // the order the timeline had. `track_index` is the stack position;
        // a clip on a track that is not in `tracks` cannot exist (`validate`
        // refuses it) and is skipped rather than defended against twice.
        let mut sources: Vec<(usize, u32)> = Vec::new();
        for clip in &selected {
            if let Some(index) = self.track_index(clip.track) {
                if !sources.iter().any(|(_, id)| *id == clip.track) {
                    sources.push((index, clip.track));
                }
            }
        }
        sources.sort_unstable();
        // The front-most source track that is not a matte track is where
        // the nest clip goes (MT-5): a matte pair nested together must land
        // where its picture was drawn, not on the matte track, where the
        // whole nest would become a matte. The front-most when all are. The
        // nest's own tracks count toward `MAX_TRACKS` like any other
        // (`format::check_caps`), so a selection that would overrun the cap
        // is caught by `finish` rather than counted twice here.
        let drawn = sources
            .iter()
            .rev()
            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
            return Ok(Outcome::Identity);
        };

        let mut next = self.clone();
        let nest_id = next.allocate_id();
        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
        for (_, id) in &sources {
            let Some(source) = self.track(*id) else {
                continue;
            };
            let track = nested_track(&mut next, source, *id != front_track);
            mapping.push((*id, track.id));
            tracks.push(track);
        }
        // The carry rule (MT-5), one pass over the mapping: a nested track
        // stays a matte only when the nested track directly behind it is the
        // copy of its source's target. A matte nested without its target
        // draws inside the nest as an ordinary track (owner, O9).
        for index in 0..tracks.len() {
            let from = mapping.get(index).map(|(from, _)| *from);
            let behind = index
                .checked_sub(1)
                .and_then(|i| mapping.get(i))
                .map(|(from, _)| *from);
            let carried = from.and_then(|from| matte_target(&self.tracks, from));
            if carried.is_none() || carried != behind {
                if let Some(track) = tracks.get_mut(index) {
                    track.matte = crate::model::TrackMatte::None;
                }
            }
        }

        // The clips move WHOLE — ids, actions, transitions and all — so
        // nothing about them has to be re-minted or re-checked. Only their
        // container changes.
        let mut inside: Vec<Clip> = Vec::with_capacity(selected.len());
        for clip in &selected {
            let Some((_, track)) = mapping.iter().find(|(from, _)| *from == clip.track) else {
                continue;
            };
            let mut moved = clip.clone();
            moved.track = *track;
            moved.start = clip.start.saturating_sub(earliest);
            inside.push(moved);
        }
        // Any sound inside means the nest clip needs a volume of its own to
        // scale it by; a nest of text and shapes gets no audio group, so the
        // inspector shows no Audio tab for something that cannot make a
        // sound.
        let audible = inside.iter().any(|c| c.audio.is_some());

        next.clips
            .retain(|c| !selected.iter().any(|s| s.id == c.id));
        next.nests.push(Nest {
            id: nest_id,
            name: match name.map(str::trim).filter(|n| !n.is_empty()) {
                Some(given) => given.to_string(),
                None => format!("Nest {}", next.nests.len().saturating_add(1)),
            },
            width: next.canvas.width,
            height: next.canvas.height,
            tracks,
            clips: inside,
        });

        let clip_id = next.allocate_id();
        // A transition INTO the selection belonged to a clip that is now
        // inside the group, so the nest clip gets the default cross
        // dissolve over whatever overlap it inherits — the same rule
        // every other op uses for a clip that gains one.
        next.clips.push(Clip {
            video: Some(VideoProps::default()),
            audio: audible.then(AudioProps::default),
            ..Clip::placed(
                clip_id,
                front_track,
                earliest,
                latest.saturating_sub(earliest),
                Source::Nest { project: nest_id },
            )
        });

        if let Err(why) = next.check_overlap_rule(&[], front_track, &[]) {
            return Ok(Outcome::Refused(why));
        }
        self.finish_placement(next, &[front_track])
    }

    /// Puts a nest clip's contents back on the timeline and removes the clip
    /// (spec §6) — the inverse of [`Project::nest_clips`].
    ///
    /// Each clip returns at `clip.start + its own start`, with fresh ids, on
    /// the track counted back from the nest clip's own: the nest's
    /// front-most NON-matte track (the front-most when all are, MT-5) lands
    /// where the nest clip was, the one behind it a track further back, a
    /// carried matte track in front of it a track further forward, and
    /// tracks missing behind are added. A clip the overlap rule refuses —
    /// or a matte clip with no track in front — goes on a new track in
    /// front, ordinary: `unnest` makes no track a matte.
    ///
    /// The nest itself is dropped when nothing else shows it; a second clip
    /// showing it keeps it, which is why the returned clips are copies.
    /// `Err` when `clip` is not a nest clip.
    pub fn unnest_clip(&self, clip: u32) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Source::Nest { project } = target.source else {
            return Err(format!("clip {clip} is not a nest clip"));
        };
        // `validate` refuses a clip pointing at a nest that is not there, so
        // this is a corrupt project rather than a caller's mistake — an
        // error either way, naming both ids.
        let nest = self
            .nest(project)
            .ok_or_else(|| format!("clip {clip} shows unknown nest {project}"))?
            .clone();

        let base = self.require_track_index(target.track)? as i64;
        // The nest's front-most non-matte track, the one the nest clip's own
        // track stands for (MT-5); the front-most when all are mattes.
        let front = nest
            .tracks
            .iter()
            .rposition(|t| t.matte.is_none())
            .unwrap_or(nest.tracks.len().saturating_sub(1)) as i64;
        let depth = |track: u32| -> i64 {
            // 0 for `front`, counting backwards; negative for a carried
            // matte track in front of it.
            match nest.tracks.iter().position(|t| t.id == track) {
                Some(index) => front - index as i64,
                None => 0,
            }
        };
        // Bounded by the track cap the project was read under, so the
        // deficit loop below can ask for at most `MAX_TRACKS` tracks and
        // `finish` refuses the result if that is too many.
        let deepest = front;

        let mut next = self.clone();
        next.clips.retain(|c| c.id != clip);

        // Tracks missing behind the destination, exactly as `paste` adds
        // them: inserting at index 0 shifts every existing track up, so the
        // destination index moves with them.
        let base = next.add_tracks_behind(deepest, base);

        // Back-most first, then time: the order clips are placed in is the
        // order the overlap rule sees them, so it has to be deterministic or
        // one nest could open two ways.
        let mut ordered: Vec<&Clip> = nest.clips.iter().collect();
        ordered.sort_by_key(|c| (std::cmp::Reverse(depth(c.track)), c.start, c.id));

        let mut landing = Landing::new(base);
        let first = next.clips.len();
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for source in ordered {
            let mut moved = source.clone();
            next.remint(&mut moved);
            fresh.insert(source.id, moved.id);
            // Translate first; the shared normalization then handles a
            // hand-written or legacy off-grid nest on the parent grid.
            moved.start = target.start.saturating_add(source.start);
            next.resnap_clip_times(&mut moved);
            landing.land(&mut next, moved, depth(source.track));
        }
        // The returning clips re-pair through their fresh ids (AU-96).
        if let Some(landed) = next.clips.get_mut(first..) {
            relink_copies(landed, &fresh);
        }

        if !next.nest_is_shown(project) {
            next.nests.retain(|n| n.id != project);
        }
        self.finish_placement(next, landing.touched())
    }
}
